let image=null,row=0;
export async function loadMomo(){try{image=new Image();image.src='art/animals/cat-ginger.webp';await image.decode();return true;}catch{image=null;return false;}}
export const momoMarkup=()=>'<ellipse pointer-events="none" cy="5" rx="18" ry="6" fill="#63794b1a"/><foreignObject x="-32" y="-57" width="64" height="64" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" class="momo-canvas" width="128" height="128" style="display:block;width:64px;height:64px;image-rendering:pixelated"></canvas></foreignObject>';
export function paintMomo(root,{walking=false,dx=0,dy=0,resting=false,time=0}={}){const canvas=root.querySelector('.momo-canvas');if(!canvas||!image)return;if(walking)row=Math.abs(dx)>Math.abs(dy)?dx<0?2:3:dy<0?1:0;const c=canvas.getContext('2d');c.clearRect(0,0,128,128);c.imageSmoothingEnabled=false;const frame=walking?1+Math.floor(time*8)%5:0;c.drawImage(image,frame*128,row*128,128,128,0,0,128,128);if(resting&&!walking){c.fillStyle='#859b8d';c.font='14px sans-serif';c.fillText('z',99,19);c.font='10px sans-serif';c.fillText('z',112,9);}}
